(function(){function initTermsPage(){const sections=Array.from(document.querySelectorAll(".terms-section"));if(!sections.length)return;const links=Array.from(document.querySelectorAll("[data-spy]"));const bar=document.querySelector(".terms-progress span");const current=document.querySelector(".terms-current");const content=document.querySelector(".terms-content");const toTop=document.getElementById("terms-back-to-top")||document.querySelector(".back-to-top");let lockUntil=0;function setActive(id,force){if(!force&&Date.now()<lockUntil)return;links.forEach((a)=>a.classList.toggle("is-active",a.dataset.spy===id));sections.forEach((s)=>s.classList.toggle("is-active",s.id===id));const sec=document.getElementById(id);if(sec&&current){const h2=sec.querySelector("h2");if(h2)current.textContent=h2.textContent;}}if("IntersectionObserver" in window){const io=new IntersectionObserver((entries)=>{entries.forEach((en)=>{if(en.isIntersecting)setActive(en.target.id);});},{rootMargin:"-35% 0px -55% 0px"});sections.forEach((s)=>io.observe(s));}function progress(){if(content&&bar){const r=content.getBoundingClientRect();const total=r.height-window.innerHeight*0.5;const done=Math.min(Math.max((window.innerHeight*0.5-r.top)/total,0),1);bar.style.transform=`scaleY(${done})`;}if(toTop){toTop.classList.toggle("is-visible",window.scrollY>400);}}window.addEventListener("scroll",progress,{passive:true});progress();function flash(explicitId){const id=explicitId||(window.location.hash?window.location.hash.slice(1):"");const sec=id&&document.getElementById(id);if(!sec||!sec.classList.contains("terms-section"))return;sec.classList.remove("is-flash");void sec.offsetWidth;sec.classList.add("is-flash");setActive(id,true);lockUntil=Date.now()+1200;}function navigateToSection(id,smooth=true){if(!id)return;const sec=document.getElementById(id);if(!sec)return;sec.scrollIntoView({behavior:smooth?"smooth":"auto",block:"start"});flash(id);}window.addEventListener("hashchange",()=>{const id=window.location.hash.slice(1);if(id){navigateToSection(id,true);}});links.forEach((link)=>{link.addEventListener("click",(e)=>{const targetId=link.dataset.spy||link.getAttribute("href")?.replace("#","");if(!targetId)return;const sec=document.getElementById(targetId);if(sec){e.preventDefault();if(history.pushState){history.pushState(null,"",`#${targetId}`);}else{window.location.hash=targetId;}navigateToSection(targetId,true);}});});if(window.location.hash){const hashId=window.location.hash.slice(1);flash(hashId);setTimeout(()=>{navigateToSection(hashId,false);},80);setTimeout(()=>{navigateToSection(hashId,true);},350);}if(toTop){toTop.addEventListener("click",()=>{window.scrollTo({top:0,behavior:"smooth"});});}}window.initTermsPage=initTermsPage;if(document.readyState==="loading"){document.addEventListener("DOMContentLoaded",initTermsPage);}else{initTermsPage();}})();